python3 -c $'import sys,json,math\nC=lambda v:v or sys.exit(\'BLOCKED\')\nx=json.load(sys.stdin)\nC(x.get(\'source\')==\'SYNTHETIC\' and x.get(\'mode\')==\'paper\' and x.get(\'position\') in (\'FLAT\',\'LONG\'))\np=x[\'prices\'];C(type(p)==list and 100<=len(p)<=2000 and all(type(z) in (float,int) and math.isfinite(z) and z>0 for z in p))\nr=[10000*(b/a-1) for a,b in zip(p,p[1:])];C(all(math.isfinite(v) and abs(v)<=2500 for v in r))\ns=[2 if v>0 else 0 if v<0 else 1 for v in r];n=len(s);t=n*7//10\nC(t>=30 and n-t>=20)\ng=[[r[i] for i in range(1,t) if s[i-1]==k] for k in range(3)]\ne=[sum(v)/len(v) if len(v)>=6 else 0 for v in g]\nq=0;w=0.;z=0\nfor i in range(t,n):\n k=s[i-1];v=int(e[k]>40+30/math.sqrt(max(1,len(g[k]))));z+=abs(v-q);w+=v*r[i]-abs(v-q)*20;q=v\nw-=q*20;z+=q;k=s[-1];a=int(len(g[k])>=6 and e[k]>40+30/math.sqrt(len(g[k])) and w>0 and z>=2);b=int(x[\'position\']==\'LONG\')\no=\'BUY\' if a and not b else \'SELL\' if b and not a else \'HOLD\'\nf=bytes(s[-8:]);h=1\nfor v in f:h=h*257+v+1\nv=h;y=[]\nwhile v>1:\n v,j=divmod(v,257);C(j>0);y.insert(0,j-1)\nC(bytes(y)==f)\nprint(json.dumps(dict(version=\'G15\',action=\'SIMULATED_\'+o+\'_ONLY\' if o!=\'HOLD\' else \'HOLD\',godel=h,roundtrip=True,train_events=t,heldout_events=n-t,heldout_net_bps=round(w,3),heldout_turnovers=z,model=\'G257_CONDITIONAL_RETURN\',fee_slippage_bps_per_side=20.,live_allowed=False,actual_orders=0,profitability_proved=False),sort_keys=True))\n'
